				update_relations_item: {
					type: Relation,
					args: {
						collection: new GraphQLNonNull(GraphQLString),
						field: new GraphQLNonNull(GraphQLString),
						data: toInputObjectType(Relation.clone('update_directus_relations'), { postfix: '_input' }).NonNull,
