 *
 * @returns Nothing
 */
export const enableTwoFactor =
	<Schema>(secret: string, otp: string): RestCommand<void, Schema> =>
	() => ({
		path: `/users/me/tfa/enable`,
		method: 'POST',
		body: JSON.stringify({
			secret,
			otp,
		}),
	});

