export type ServerHealthOutput = {
	status: 'ok' | 'warn' | 'error';
	releaseId?: string;
	serviceId?: string;
	checks?: {
		[name: string]: Record<string, any>[];
	};
};

/**
 * Get the current health status of the server.
 * @returns The current health status of the server.
 */
export const serverHealth =
	<Schema>(): RestCommand<ServerHealthOutput, Schema> =>
	() => ({
		method: 'GET',
		path: '/server/health',
	});

export * from './graphql.js';
export * from './health.js';
export * from './info.js';
export * from './openapi.js';
export * from './ping.js';

import type { RestCommand } from '../../types.js';

// TODO can we type this?
export type OpenApiSpecOutput = Record<string, any>;

/**
 * Retrieve the OpenAPI spec for the current project.
 * @returns Object conforming to the OpenAPI Specification
 */
export const readOpenApiSpec =
	<Schema>(): RestCommand<OpenApiSpecOutput, Schema> =>
	() => ({
		method: 'GET',
		path: '/server/specs/oas',
	});

import type { RestCommand } from '../../types.js';

/**
 * Ping... pong! 🏓
 * @returns Pong
 */
export const serverPing =
	<Schema>(): RestCommand<string, Schema> =>
	() => ({
		method: 'GET',
		path: '/server/ping',
	});

import type { RestCommand } from '../../types.js';

/**
 * Resets both the data and schema cache of Directus. This endpoint is only available to admin users.
 * @returns Nothing
 */
export const clearCache =
	<Schema>(): RestCommand<void, Schema> =>
	() => ({
		method: 'POST',
		path: `/utils/cache/clear`,
	});

import type { Query } from '../../../index.js';
import type { DirectusFile } from '../../../schema/file.js';
import type { RestCommand } from '../../types.js';

export type FileFormat = 'csv' | 'json' | 'xml' | 'yaml';

/**
 * Export a larger data set to a file in the File Library
 * @returns Nothing
 */
export const utilsExport =
	<Schema, TQuery extends Query<Schema, Schema[Collection]>, Collection extends keyof Schema>(
		collection: Collection,
		format: FileFormat,
		query: TQuery,
		file: Partial<DirectusFile<Schema>>,
	): RestCommand<void, Schema> =>
	() => ({
		method: 'POST',
		path: `/utils/export/${collection as string}`,
		body: JSON.stringify({ format, query, file }),
	});

import type { RestCommand } from '../../types.js';

// TODO better options for ouput typing

/**
 * Trigger a flow
 * @param method
 * @param id
 * @param data
 * @returns Result of the flow, if any.
 */
export const triggerFlow =
	<Schema>(method: 'GET' | 'POST', id: string, data?: Record<string, string>): RestCommand<unknown, Schema> =>
	() => {
		if (method === 'GET') {
			return {
				path: `/flows/trigger/${id}`,
				params: data ?? {},
				method: 'GET',
			};
		}

		return {
			path: `/flows/trigger/${id}`,
			body: JSON.stringify(data ?? {}),
			method: 'POST',
		};
	};

import type { RestCommand } from '../../types.js';

/**
 * Generate a hash for a given string.
 * @param string String to hash.
 * @returns Hashed string.
 */
export const generateHash =
	<Schema>(string: string): RestCommand<string, Schema> =>
	() => ({
		method: 'POST',
		path: `/utils/hash/generate`,
		body: JSON.stringify({ string }),
	});

/**
 * Verify a string with a hash.
 * @param string Source string.
 * @param hash Hash you want to verify against.
 * @returns Boolean.
 */
export const verifyHash =
	<Schema>(string: string, hash: string): RestCommand<boolean, Schema> =>
	() => ({
		method: 'POST',
		path: `/utils/hash/verify`,
		body: JSON.stringify({ string, hash }),
	});

